import{_ as n,C as r,o as t,c as l,j as a,a as i,b as d,w as s,E as c,a2 as h,a3 as u}from"./chunks/framework.pb1iZPmZ.js";const P=JSON.parse('{"title":"14.1 System Design: Requirements & Capacity Estimation","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.1-requirements-estimation.md","filePath":"system-design/14.1-requirements-estimation.md"}'),m={name:"system-design/14.1-requirements-estimation.md"};function g(p,e,f,y,b,S){const o=r("Mermaid");return t(),l("div",null,[e[1]||(e[1]=a("h1",{id:"_14-1-system-design-requirements-capacity-estimation",tabindex:"-1"},[i("14.1 System Design: Requirements & Capacity Estimation "),a("a",{class:"header-anchor",href:"#_14-1-system-design-requirements-capacity-estimation","aria-label":'Permalink to "14.1 System Design: Requirements & Capacity Estimation"'},"​")],-1)),(t(),d(h,null,{default:s(()=>[c(o,{id:"mermaid-3",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Staff%5B5%2C000%20Hospital%20Staff%20%2F%20Clinicians%5D%20--%3E%20DailyActive%5B2%2C500%20Daily%20Active%20Clinicians%20DAU%5D%0A%20%20%20%20DailyActive%20--%3E%20Shifts%5BShift%20Handover%20Peaks%3A%207%20AM%2C%203%20PM%2C%2011%20PM%5D%0A%20%20%20%20Shifts%20--%3E%20PeakRPS%5BPeak%20Traffic%3A%20~50%20-%20150%20RPS%5D%0A%20%20%20%20PeakRPS%20--%3E%20DBRead%5BDB%20Reads%3A%20~300%20IOPS%20on%20Hydration%5D%0A%20%20%20%20PeakRPS%20--%3E%20DBWrite%5BDB%20Writes%3A%20~20%20-%2050%20IOPS%20on%20Session%20Upsert%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=u('<hr><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>System design capacity estimation is the mathematical process of calculating the hardware, network bandwidth, storage footprint, and compute resources required to support an application&#39;s user base reliably without over-provisioning or crashing under peak load.</p><hr><h2 id="_2-requirements-of-this-system" tabindex="-1">2. Requirements of This System <a class="header-anchor" href="#_2-requirements-of-this-system" aria-label="Permalink to &quot;2. Requirements of This System&quot;">​</a></h2><h3 id="functional-requirements" tabindex="-1">Functional Requirements <a class="header-anchor" href="#functional-requirements" aria-label="Permalink to &quot;Functional Requirements&quot;">​</a></h3><ol><li><strong>Account Registration</strong>: Allow new medical staff to create an account with username, password, and name.</li><li><strong>Session Authentication</strong>: Authenticate credentials and establish a secure, stateful session cookie (<code>connect.sid</code>).</li><li><strong>Session Invalidation</strong>: Allow immediate session termination (<code>POST /logout</code>) on shared terminals.</li><li><strong>Protected Dashboard Access</strong>: Guard <code>/dashboard</code> and dynamically render the employee&#39;s name.</li></ol><h3 id="non-functional-requirements" tabindex="-1">Non-Functional Requirements <a class="header-anchor" href="#non-functional-requirements" aria-label="Permalink to &quot;Non-Functional Requirements&quot;">​</a></h3><ol><li><strong>Low Latency</strong>: Initial page load under 200ms; login response under 100ms.</li><li><strong>High Availability</strong>: 99.9% uptime (critical for 24/7 hospital clinical access).</li><li><strong>Data Security &amp; Privacy</strong>: Protection against unauthorized session hijacking; HIPAA compliance readiness.</li><li><strong>Immediate Consistency</strong>: When a user registers or logs out, the state change must be immediately consistent across all queries.</li></ol><hr><h2 id="_3-capacity-resource-arithmetic" tabindex="-1">3. Capacity &amp; Resource Arithmetic <a class="header-anchor" href="#_3-capacity-resource-arithmetic" aria-label="Permalink to &quot;3. Capacity &amp; Resource Arithmetic&quot;">​</a></h2><h3 id="assumptions-hospital-enterprise-scale" tabindex="-1">Assumptions (Hospital Enterprise Scale) <a class="header-anchor" href="#assumptions-hospital-enterprise-scale" aria-label="Permalink to &quot;Assumptions (Hospital Enterprise Scale)&quot;">​</a></h3><ul><li><strong>Total Hospital Employees</strong>: 10,000 registered staff.</li><li><strong>Daily Active Clinicians (DAU)</strong>: 3,000 users.</li><li><strong>Clinician Login Actions per Day</strong>: Average 6 logins/logouts per shift across shared nursing terminals.</li><li><strong>Total Login Requests per Day</strong>: $3,000 \\times 6 = 18,000$ logins/day.</li><li><strong>Dashboard Hits per Day</strong>: $3,000 \\times 40 = 120,000$ page impressions/day.</li></ul><h3 id="request-rate-rps-calculation" tabindex="-1">Request Rate (RPS) Calculation <a class="header-anchor" href="#request-rate-rps-calculation" aria-label="Permalink to &quot;Request Rate (RPS) Calculation&quot;">​</a></h3><ul><li><strong>Average RPS</strong>: $\\frac{120,000 \\text{ requests}}{86,400 \\text{ seconds}} \\approx 1.4 \\text{ RPS}$.</li><li><strong>Peak Hour Factor</strong>: Hospital shift changes occur at 7:00 AM, 3:00 PM, and 11:00 PM. Traffic during these 30-minute peak windows is 15x average traffic.</li><li><strong>Peak RPS</strong>: $1.4 \\times 15 \\approx \\mathbf{21 \\text{ RPS}}$ baseline, scaling to $\\mathbf{210 \\text{ RPS}}$ at 10x network bursts.</li></ul><h3 id="storage-capacity-calculations" tabindex="-1">Storage Capacity Calculations <a class="header-anchor" href="#storage-capacity-calculations" aria-label="Permalink to &quot;Storage Capacity Calculations&quot;">​</a></h3><ol><li><strong>Employee Profile Data</strong>: <ul><li>Schema size per employee: <code>_id</code> (12B) + <code>username</code> (40B) + <code>password</code> (60B) + <code>name</code> (40B) + BSON overhead $\\approx 200 \\text{ bytes}$.</li><li>10,000 employees $\\times 200 \\text{ bytes} \\approx \\mathbf{2 \\text{ MB}}$ (entire table easily fits in memory).</li></ul></li><li><strong>Session Store Data</strong>: <ul><li>Session document size: <code>_id</code> (40B) + <code>session JSON</code> (150B) + <code>expires</code> (8B) $\\approx 300 \\text{ bytes}$.</li><li>Active daily sessions: 3,000 concurrent sessions $\\times 300 \\text{ bytes} \\approx \\mathbf{900 \\text{ KB}}$.</li><li>With a 24-hour TTL, storage never exceeds 5 MB.</li></ul></li></ol><h3 id="network-bandwidth" tabindex="-1">Network Bandwidth <a class="header-anchor" href="#network-bandwidth" aria-label="Permalink to &quot;Network Bandwidth&quot;">​</a></h3><ul><li>Average page payload: <code>login.html</code> (16 KB) + fonts/CSS (40 KB) $\\approx 56 \\text{ KB}$.</li><li>Peak bandwidth: $21 \\text{ RPS} \\times 56 \\text{ KB} \\approx \\mathbf{1.17 \\text{ MB/sec}} \\approx \\mathbf{9.4 \\text{ Mbps}}$.</li></ul><hr><h2 id="_4-what-breaks-first-at-scale" tabindex="-1">4. What Breaks First at Scale <a class="header-anchor" href="#_4-what-breaks-first-at-scale" aria-label="Permalink to &quot;4. What Breaks First at Scale&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Scale Level</th><th style="text-align:left;">Traffic Volume</th><th style="text-align:left;">First Breaking Point in Code</th><th style="text-align:left;">Root Cause &amp; Failure Symptom</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>10x Load</strong></td><td style="text-align:left;">~200 RPS</td><td style="text-align:left;">Plaintext comparison / event loop delay</td><td style="text-align:left;">Password matching delays under concurrency.</td></tr><tr><td style="text-align:left;"><strong>100x Load</strong></td><td style="text-align:left;">~2,000 RPS</td><td style="text-align:left;">MongoDB Session IOPS</td><td style="text-align:left;">Every request hits <code>sessions</code> and <code>User.findById</code> in <code>app.js:43</code>, exhausting disk IOPS.</td></tr><tr><td style="text-align:left;"><strong>1000x Load</strong></td><td style="text-align:left;">~20,000 RPS</td><td style="text-align:left;">Single Node.js TCP Listener</td><td style="text-align:left;">Single-threaded event loop saturates CPU; TCP backlog queue drops incoming handshakes.</td></tr></tbody></table><hr><h2 id="_5-senior-engineering-improvements" tabindex="-1">5. Senior Engineering Improvements <a class="header-anchor" href="#_5-senior-engineering-improvements" aria-label="Permalink to &quot;5. Senior Engineering Improvements&quot;">​</a></h2><ol><li>Introduce <strong>Redis</strong> to offload session read traffic from MongoDB disk to RAM.</li><li>Deploy the Express application across a cluster of 4–8 worker processes behind an Nginx or AWS Application Load Balancer.</li><li>Cache static assets (<code>login.html</code>, web fonts, CSS) on a Content Delivery Network (Cloudflare).</li></ol><hr><h2 id="_6-30-second-spoken-answer" tabindex="-1">6. 30-Second Spoken Answer <a class="header-anchor" href="#_6-30-second-spoken-answer" aria-label="Permalink to &quot;6. 30-Second Spoken Answer&quot;">​</a></h2><blockquote><p>&quot;At a regional hospital scale of 10,000 staff members, average traffic is around 2 requests per second, peaking at 25 to 50 RPS during shift changes. Storage needs are very modest—under 10 megabytes total for employee records and active sessions. The first bottleneck at scale is not data volume but database read IOPS caused by querying MongoDB on every request in the hydration middleware, which I would resolve by placing Redis ahead of MongoDB.&quot;</p></blockquote>',28))])}const q=n(m,[["render",g]]);export{P as __pageData,q as default};
